"""Packaging inventory for persistent megakernel artifacts.

This module owns only what the wheel builds and may select: architecture,
persistent-grid width, compiler target identity, and artifact-family membership.
Silicon capabilities and measured rates remain compiler-owned calibration data.
"""

from dataclasses import dataclass


GENERATED_DECODE = "generated_decode"
WHOLE_MODEL = "whole_model"
PREFILL = "prefill"
_ARTIFACT_FAMILIES = frozenset({GENERATED_DECODE, WHOLE_MODEL, PREFILL})


@dataclass(frozen=True)
class DeployTarget:
    """One GPU/grid cell in the shipped artifact inventory."""

    arch_num: int
    num_sms: int
    compiler_gpu: str
    artifact_families: frozenset[str]

    def __post_init__(self) -> None:
        if (not isinstance(self.arch_num, int) or isinstance(self.arch_num, bool)
                or self.arch_num <= 0):
            raise ValueError("deploy target arch_num must be a positive integer")
        if (not isinstance(self.num_sms, int) or isinstance(self.num_sms, bool)
                or self.num_sms <= 0):
            raise ValueError("deploy target num_sms must be a positive integer")
        if not isinstance(self.compiler_gpu, str) or not self.compiler_gpu.strip():
            raise ValueError("deploy target compiler_gpu must be nonempty")
        if not isinstance(self.artifact_families, frozenset):
            raise TypeError("deploy target artifact_families must be a frozenset")
        if not self.artifact_families:
            raise ValueError("deploy target must ship at least one artifact family")
        unknown = self.artifact_families - _ARTIFACT_FAMILIES
        if unknown:
            raise ValueError(f"unknown deploy artifact families: {sorted(unknown)!r}")

    @property
    def arch(self) -> str:
        return f"sm{int(self.arch_num)}"


# Adding an architecture does not imply that every artifact family ships for
# it. Family membership is explicit so a new target cannot silently grow the
# wheel or expose an unbuilt runtime path.
DEPLOY_TARGETS = (
    DeployTarget(
        arch_num=80,
        num_sms=108,
        compiler_gpu="NVIDIA A100-SXM4-80GB",
        artifact_families=frozenset({GENERATED_DECODE}),
    ),
    DeployTarget(
        arch_num=86,
        num_sms=72,
        compiler_gpu="NVIDIA A10",
        artifact_families=frozenset({GENERATED_DECODE}),
    ),
    # Tried Qwen3.5-4B B1 at 80 CTAs on RTX 3090: 10.495 ms versus
    # 10.488 ms at 82 CTAs (1.0007x latency); keeping the full 82-SM grid.
    DeployTarget(
        arch_num=86,
        num_sms=82,
        compiler_gpu="NVIDIA GeForce RTX 3090",
        artifact_families=frozenset({GENERATED_DECODE}),
    ),
    DeployTarget(
        arch_num=89,
        num_sms=58,
        compiler_gpu="NVIDIA L4",
        artifact_families=frozenset({GENERATED_DECODE}),
    ),
    DeployTarget(
        arch_num=90,
        num_sms=132,
        compiler_gpu="NVIDIA H100 80GB HBM3",
        artifact_families=frozenset({GENERATED_DECODE, WHOLE_MODEL, PREFILL}),
    ),
    DeployTarget(
        arch_num=90,
        num_sms=114,
        compiler_gpu="NVIDIA H100 80GB HBM3",
        artifact_families=frozenset({WHOLE_MODEL, PREFILL}),
    ),
    DeployTarget(
        arch_num=100,
        num_sms=148,
        compiler_gpu="NVIDIA B200",
        artifact_families=frozenset({GENERATED_DECODE, WHOLE_MODEL}),
    ),
    DeployTarget(
        arch_num=120,
        num_sms=188,
        compiler_gpu="NVIDIA RTX PRO 6000 Blackwell Server Edition",
        artifact_families=frozenset({GENERATED_DECODE}),
    ),
)

_cells = tuple((target.arch_num, target.num_sms) for target in DEPLOY_TARGETS)
if len(_cells) != len(set(_cells)):
    raise RuntimeError("duplicate cells in deploy target inventory")
_covered_families = frozenset().union(*(
    target.artifact_families for target in DEPLOY_TARGETS
))
if _covered_families != _ARTIFACT_FAMILIES:
    raise RuntimeError(
        "deploy target inventory does not cover every artifact family")
del _cells, _covered_families


def deploy_targets_for(artifact_family: str) -> tuple[DeployTarget, ...]:
    """Return the ordered shipped targets for one artifact family."""

    family = str(artifact_family)
    if family not in _ARTIFACT_FAMILIES:
        raise ValueError(f"unknown deploy artifact family {family!r}")
    return tuple(
        target for target in DEPLOY_TARGETS
        if family in target.artifact_families
    )


def deploy_sm_counts_for(artifact_family: str) -> dict[int, tuple[int, ...]]:
    """Group one family's shipped grid widths by architecture."""

    result: dict[int, list[int]] = {}
    for target in deploy_targets_for(artifact_family):
        result.setdefault(int(target.arch_num), []).append(int(target.num_sms))
    return {arch: tuple(counts) for arch, counts in result.items()}


def select_deploy_num_ctas(
    artifact_family: str,
    arch_num: int,
    device_sms: int,
) -> int | None:
    """Select the largest shipped grid for ``artifact_family`` that fits."""

    if int(device_sms) <= 0:
        return None
    fits = (
        target.num_sms
        for target in deploy_targets_for(artifact_family)
        if target.arch_num == int(arch_num) and target.num_sms <= int(device_sms)
    )
    return max(fits, default=None)


__all__ = [
    "DEPLOY_TARGETS",
    "GENERATED_DECODE",
    "PREFILL",
    "WHOLE_MODEL",
    "DeployTarget",
    "deploy_sm_counts_for",
    "deploy_targets_for",
    "select_deploy_num_ctas",
]
